const areas = [
  {title:'Authentication and OTP flows',scope:'Audit src/app/(auth), src/lib/auth, session cookies, signup/reset/2FA. Focus OTP correctness, resend/replay, rate limit, redirect/session safety and tests.'},
  {title:'Prisma schema, migrations, seed and persistence',scope:'Audit prisma/schema.prisma, prisma/migrations, seed, Prisma config and DB runtime. Focus schema/migration drift, constraints, dangerous scripts, production migration readiness.'},
  {title:'Next.js API routes and tenant authorization',scope:'Audit src/app/api routes and shared API/tenant/RBAC helpers. Focus auth bypass, tenant isolation, validation, CSRF, rate limits and input trust.'},
  {title:'Commerce, billing, payments and order services',scope:'Audit src/lib/services and src/lib/payments plus callers. Focus transactions, idempotency, money arithmetic, payment/webhook verification, stock/coupon races, billing and order transitions.'},
  {title:'Storefront, proxy routing and public rendering',scope:'Audit src/app/store, src/proxy.ts, storefront helpers and theme rendering. Focus host/slug routing, XSS, data leaks, cache, checkout and unsafe redirects.'},
  {title:'Admin, super-admin and account UI flows',scope:'Audit src/app/admin, src/app/super-admin, src/app/account, onboarding and shared UI. Focus server render exceptions, permission gates, missing-store states, action wiring, navigation and accessibility.'},
  {title:'Configuration, deployment and operational security',scope:'Audit package manifests/scripts, Docker/Compose, Next config, env validation, logging, storage, cron, CI/deployment configs. Focus build/start blockers, secrets, insecure defaults and CI failures on current main.'},
  {title:'Tests, static quality and cross-module regressions',scope:'Audit checked-in tests, package scripts, ESLint/TypeScript config, CI and coverage. Inspect failed GitHub Actions for commit 5296e77 if logs are accessible; identify untested critical paths.'}
];
const finding={type:'object',properties:{severity:{type:'string'},file:{type:'string'},line:{type:'string'},title:{type:'string'},evidence:{type:'string'},impact:{type:'string'},recommendation:{type:'string'},source_url:{type:'string'}},required:['severity','file','line','title','evidence','impact','recommendation','source_url']};
const schema=JSON.stringify({type:'object',properties:{area:{type:'string'},confidence:{type:'string'},findings:{type:'array',items:finding},checks_performed:{type:'array',items:{type:'string'}},limitations:{type:'array',items:{type:'string'}}},required:['area','confidence','findings','checks_performed','limitations']});
const results=await parallel('Audit ATLaS repository areas',()=>areas.map(a=>agent(
  'Audit exactly one area of public repository https://github.com/shazzad098/ATLaS at immutable main commit 5296e77bcaef67245b10579fb79b42fed48c3458. Area: '+a.title+'. Scope: '+a.scope+'\nUse public GitHub source/raw pages or API. Read actual code and cite precise file + line(s) and URL. Verify suspected defects against callers/tests/schema. Only actionable, reproducible bugs/security/runtime/CI/test issues; no style or speculation, and do not report fixed issues. Never modify repository. Return JSON schema: area string, confidence string, findings array (severity Critical/High/Medium/Low, file, line, title, evidence, impact, recommendation, source_url), checks_performed string array, limitations string array. For no confirmed bugs use empty findings. Include sound patterns in checks_performed. Do not audit outside assigned area.',
  {brief:'Audit '+a.title,schema,sandbox:'shared',effort_level:'lite'}
)),{schema});
const good=results.filter(r=>r.ok).map(r=>r.value);
const failed=results.map((r,i)=>r.ok?null:{area:areas[i].title,code:r.error.code,message:r.error.message}).filter(Boolean);
const rs=JSON.stringify({type:'object',properties:{overall_assessment:{type:'string'},highest_priority_findings:{type:'array',items: finding},confirmed_count:{type:'number'},by_severity:{type:'string'},ci_assessment:{type:'string'},coverage_gaps:{type:'array',items:{type:'string'}},positive_patterns:{type:'array',items:{type:'string'}}},required:['overall_assessment','highest_priority_findings','confirmed_count','by_severity','ci_assessment','coverage_gaps','positive_patterns']});
const reduced=await agent('Synthesize area results for the user for repository https://github.com/shazzad098/ATLaS at main 5296e77bcaef67245b10579fb79b42fed48c3458. Do not browse or invent. Deduplicate; preserve evidence/source links and confirmed/uncertain distinctions. Prioritize, count unique confirmed findings by severity, state CI status only if supported, list audit limits and positive patterns. Results: '+JSON.stringify(good)+'; failed areas: '+JSON.stringify(failed),{brief:'Synthesize ATLaS audit findings',schema:rs,sandbox:'shared',effort_level:'standard'});
return {repository:'https://github.com/shazzad098/ATLaS',commit:'5296e77bcaef67245b10579fb79b42fed48c3458',areas:good,area_failures:failed,synthesis:reduced.ok?reduced.value:null,synthesis_failure:reduced.ok?null:reduced.error};

